scripts_as_text.match_v101.py:
"""Freeze all public-practice GC o/A pairs with corroborated EVA word identities."""

import argparse
from collections import Counter, defaultdict
import csv
from hashlib import sha256
import json
from pathlib import Path
import re
import sys


WORK = Path(__file__).resolve().parent
DEFAULT_REPO = WORK.parent / "voynich-swarm"
DEFAULT_ALLEN = WORK.parent / "voynich-plume-spacing-work"
TRANSCRIPTIONS = {"gc": "GC2a-n.txt", "zl": "ZL3b-n.txt", "it": "IT2a-n.txt"}
LINE = re.compile(r"^<(f\d+[rv]\d*\.\d+),[^>]+>\s*(.*)$")
VARIANTS = "oA"


def hash_file(path):
    return sha256(path.read_bytes()).hexdigest()


def raw_lines(path):
    rows = {}
    for text in path.read_text(encoding="utf-8-sig").splitlines():
        match = LINE.fullmatch(text)
        if match:
            rows[match[1]] = text
    return rows


def matched_words(corpus, ivtff, paths):
    train, _ = corpus.split_pages("practice", "gc")
    languages = ("zl", "it")
    layers = {name: {line.id: line for page in corpus.pages(name) for line in page.lines} for name in languages}
    raw = {name: raw_lines(path) for name, path in paths.items()}
    groups = defaultdict(lambda: {letter: [] for letter in VARIANTS})
    for page in train:
        for line in page.lines:
            if line.unit != "P" or any(
                line.id not in layers[name] or len(layers[name][line.id].words) != len(line.words)
                for name in languages
            ):
                continue
            for word_index, spelling in enumerate(line.words):
                if len(spelling) < 2 or ivtff.uncertain(spelling) or sum(spelling.count(c) for c in VARIANTS) != 1:
                    continue
                zl, it = (layers[name][line.id].words[word_index] for name in languages)
                if zl != it or ivtff.uncertain(zl):
                    continue
                gc_index = next(index for index, char in enumerate(spelling) if char in VARIANTS)
                target = spelling[gc_index]
                frame = spelling[:gc_index] + "_" + spelling[gc_index + 1:]
                groups[(page.id, page.hand, frame, zl)][target].append({
                    "locus": line.id,
                    "word_ordinal_1based": word_index + 1,
                    "glyph_index_0based_in_gc_word": gc_index,
                    "gc": spelling,
                    "zl": zl,
                    "it": it,
                    "preceding_zl_word": layers["zl"][line.id].words[word_index - 1] if word_index else None,
                    "following_zl_word": (
                        layers["zl"][line.id].words[word_index + 1] if word_index + 1 < len(line.words) else None
                    ),
                    "parsed_line_word_count": len(line.words),
                    "raw_locus_rows": {name: layer[line.id] for name, layer in raw.items()},
                })

    pairs = []
    for (page, hand, frame, eva), twins in groups.items():
        # Counterfactual word-pairs are paired in source encounter order, with no reuse.
        for lower, upper in zip(twins["o"], twins["A"]):
            pairs.append({
                "pair_id": f"pair-{len(pairs) + 1:02}", "page": page, "hand": hand,
                "v101_frame": frame, "common_eva": eva, "members": {"o": lower, "A": upper},
            })
    return pairs


def coordinate_hints(pairs, words_path, pages_path):
    pages = {}
    loci = {row["locus"] for pair in pairs for row in pair["members"].values()}
    rows_by_locus = defaultdict(list)
    with words_path.open(newline="") as stream:
        for row in csv.DictReader(stream, delimiter="\t"):
            if row["locus"] in loci:
                rows_by_locus[row["locus"]].append(row)
    if pages_path:
        with pages_path.open(newline="") as stream:
            pages = {row["image"]: row for row in csv.DictReader(stream, delimiter="\t")}

    for pair in pairs:
        for member in pair["members"].values():
            hints = []
            for row in rows_by_locus[member["locus"]]:
                if "".join(row["reading"].split()) != member["zl"]:
                    continue
                fields = ("box_x0", "box_y0", "box_x1", "box_y1")
                if not all(row.get(key) for key in fields):
                    continue
                hints.append({
                    "allen_word_id": row["word_id"], "allen_word_ordinal_1based": int(row["word"]),
                    "allen_same_ordinal": int(row["word"]) == member["word_ordinal_1based"],
                    "native_xyxy": [int(row[key]) for key in fields], "image": row["image"],
                    "canvas": pages.get(row["image"], {}).get("iiif_canvas"),
                    "native_image": pages.get(row["image"], {}).get("iiif_image"),
                })
            member["allen_coordinate_hints"] = hints


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=DEFAULT_REPO)
    parser.add_argument("--allen-words", type=Path, default=DEFAULT_ALLEN / "words.tsv")
    parser.add_argument("--allen-pages", type=Path, default=DEFAULT_ALLEN / "pages.tsv")
    args = parser.parse_args()
    sys.path.insert(0, str(args.repo.resolve()))
    from vs import corpus, ivtff

    paths = {name: args.repo / "data" / "raw" / file for name, file in TRANSCRIPTIONS.items()}
    pairs = matched_words(corpus, ivtff, paths)
    if args.allen_words.is_file():
        coordinate_hints(pairs, args.allen_words, args.allen_pages if args.allen_pages.is_file() else None)
    by_hand = dict(sorted(Counter(pair["hand"] for pair in pairs).items()))
    assert len(pairs) == 23 and len({pair["page"] for pair in pairs}) == 20
    assert by_hand == {"1": 2, "2": 11, "3": 10}
    dataset = {
        "split": "public practice training only from the pinned ZL split definition",
        "selection": "Certain paragraph words with exactly one GC o/A at the same position in a complete same-page GC word frame. Require equal GC/ZL/IT parsed counts on each source locus and identical certain ZL and IT words at both reparsed ordinals. Keep all matched pairs, using source encounter order without reusing occurrences. No images are consulted for selection.",
        "ordinal_limits": "Equal-length line frames and matching independent words do not establish physical registration. Word ordinals refer to the Swarm parser, which splits uncertain commas. Allen readings are geometric leads only, even when an ordinal agrees. A unique or repeated EVA name requires independent whole-word location on native scans.",
        "sources": {
            "glyph_key": "https://voynich.nu/img/extra/v101a.jpg",
            "scan_catalogue": "https://collections.library.yale.edu/manifests/2002046",
            "allen_boxes": "https://ryanallen.com/voynich/glyph-map.html",
            "transcriptions": {name: {"file": file, "sha256": hash_file(paths[name]),
                                         "url": f"https://www.voynich.nu/data/{file}"}
                               for name, file in TRANSCRIPTIONS.items()},
        },
        "counts": {"pairs": len(pairs), "pages": len({pair["page"] for pair in pairs}), "pairs_by_hand": by_hand},
        "pairs": pairs,
    }
    if args.allen_words.is_file():
        dataset["sources"]["allen_words_sha256"] = hash_file(args.allen_words)
    if args.allen_pages.is_file():
        dataset["sources"]["allen_pages_sha256"] = hash_file(args.allen_pages)
    print(json.dumps(dataset, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()

scripts_as_text.match_positions.py:
"""Locate frozen v101 contrast members using complete aligned EVA word rows."""
from collections import defaultdict
import csv
import json
from pathlib import Path

from vs import corpus

ROOT = Path(__file__).resolve().parent
CANDIDATES = json.loads((ROOT / "candidates.json").read_text())["pairs"]


def table(filename):
    with (ROOT / filename).open(newline="") as source:
        yield from csv.DictReader(source, delimiter="\t")


def reading(row):
    return "".join(row["reading"].split())


def rect(row, prefix="", keys=("x0", "y0", "x1", "y1")):
    try:
        box = [int(row[prefix + key]) for key in keys]
    except (KeyError, ValueError):
        return None
    if box[0] >= box[2] or box[1] >= box[3]:
        return None
    return box


def lcs_table(a, b):
    out = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i, x in enumerate(a, 1):
        for j, y in enumerate(b, 1):
            out[i][j] = (out[i-1][j-1] + 1 if x == y
                         else max(out[i-1][j], out[i][j-1]))
    return out


def choose_position(zl_words, target_index, indexed):
    donor_words = [reading(row) for row in indexed]
    table_before = lcs_table(zl_words, donor_words)
    best = table_before[-1][-1]
    if len(donor_words) < 2 or best < min(2, len(zl_words)):
        return None, {"reason": "insufficient whole-line anchors", "optimal_anchors": best}
    after = lcs_table(list(reversed(zl_words)), list(reversed(donor_words)))
    admissible = [
        j for j, word in enumerate(donor_words)
        if word == zl_words[target_index]
        and table_before[target_index][j] + 1
        + after[len(zl_words) - target_index - 1][len(donor_words) - j - 1] == best
    ]
    absent = lcs_table(zl_words[:target_index] + zl_words[target_index+1:], donor_words)[-1][-1] == best
    context = {"optimal_anchors": best, "donor_word_count": len(donor_words),
               "zl_word_count": len(zl_words), "omission_is_optimal": absent,
               "admissible_word_ids": [indexed[j]["word_id"] for j in admissible]}
    if len(admissible) != 1 or absent:
        return None, dict(context, reason="target missing or ambiguous across optimal alignments")
    return indexed[admissible[0]], context


def geometry(candidates, page_map, words, letters, pages):
    result = []
    for pair in candidates:
        for symbol in ("o", "A"):
            member = pair["members"][symbol]
            locus = member["locus"]
            zi = int(member["word_ordinal_1based"]) - 1
            line = next(ln for ln in page_map[pair["page"]].lines if ln.id == locus)
            assert line.words[zi] == member["zl"] == member["it"] == pair["common_eva"]
            row, detail = choose_position(list(line.words), zi, words[locus])
            entry = {
                "pair_id": pair["pair_id"], "symbol": symbol, "page": pair["page"], "hand": pair["hand"],
                "locus": locus, "zl_word_rank_1based": zi + 1, "expected_word": member["zl"],
                "join": detail, "available": False,
            }
            if row is not None:
                glyphs = letters[row["word_id"]]
                if "".join(g["eva"] for g in glyphs) != member["zl"]:
                    detail["reason"] = "letter-coordinate sequence differs from the matched EVA word"
                else:
                    possible = [g for g in glyphs if g["eva"] == "o" and rect(g)]
                    if len(possible) != 1:
                        detail["reason"] = "no unique geometrically located EVA o in the aligned word"
                    elif possible[0]["image"] != row["image"] or not rect(row, "box_"):
                        detail["reason"] = "incompatible raster or word box"
                    else:
                        letter = possible[0]
                        entry.update({
                            "available": True, "image": row["image"],
                            "iiif_image": pages[row["image"]]["iiif_image"],
                            "iiif_canvas": pages[row["image"]]["iiif_canvas"],
                            "word_rect": rect(row, "box_"), "glyph_rect": rect(letter),
                            "glyph_center": [float(letter["cx"]), float(letter["cy"])],
                            "word_box_id": row["word_id"], "letter_ordinal_1based": int(letter["letter"]),
                            "glyph_trust": letter["trust"],
                        })
            result.append(entry)
    return result


def main():
    relevant = {i["locus"] for pair in CANDIDATES for i in pair["members"].values()}
    words = defaultdict(list)
    for row in table("words.tsv"):
        if row["locus"] in relevant:
            words[row["locus"]].append(row)
    for word_rows in words.values():
        word_rows.sort(key=lambda row: int(row["word"]))
    word_ids = {row["word_id"] for rows in words.values() for row in rows}
    letters = defaultdict(list)
    for glyph in table("letters.tsv"):
        if glyph["word_id"] in word_ids:
            letters[glyph["word_id"]].append(glyph)
    for glyphs in letters.values():
        glyphs.sort(key=lambda row: int(row["letter"]))
    scan_index = {row["image"]: row for row in table("pages.tsv")}
    training, _ = corpus.split_pages("practice")
    page_map = {p.id: p for p in training}
    identified = geometry(CANDIDATES, page_map, words, letters, scan_index)
    (ROOT / "geometry-frozen.json").write_text(json.dumps(identified, indent=2) + "\n")
    for row in identified:
        print(row["pair_id"], row["symbol"], row["available"],
              row.get("word_box_id", row["join"].get("reason")),
              row.get("glyph_rect", row["join"].get("admissible_word_ids")))


if __name__ == "__main__":
    main()

scripts_as_text.score_blind_shapes.py:
"""Unmask two frozen blind ratings against v101 and summarize paired shapes."""

import argparse
from collections import Counter, defaultdict
from hashlib import sha256
import json
from pathlib import Path


V101_REFERENCE = {"o": "R1", "A": "R2"}
PROJECTION_REFERENCE = {"absent": "R1", "present": "R2"}
DEFINITE = {
    "family": ("loop_family", "other_family"),
    "closure": ("closed", "visibly_open"),
    "aperture": ("top", "bottom", "left", "right", "none"),
    "projection": ("present", "absent"),
    "reference": ("R1", "R2"),
}
FIELD_ALIASES = {
    "aperture": "aperture_side",
    "projection": "lower_right_projection",
    "reference": "neutral_reference",
}
VALUE_ALIASES = {
    "family": {"loop": "loop_family", "other": "other_family"},
    "closure": {"open": "visibly_open"},
    "aperture": {},
    "projection": {"yes": "present", "no": "absent"},
    "reference": {"r1": "R1", "r2": "R2"},
}
EXTRA = {"aperture": ("ambiguous",), "reference": ("neither",)}
ORIENTATIONS = ("expected", "reverse", "both_R1", "both_R2", "no_consensus")


def normalized_rating(rating):
    """Keep unresolved, neither, ambiguity and missing data distinct."""
    result = {}
    for field, definite in DEFINITE.items():
        raw = rating.get(field, rating.get(FIELD_ALIASES.get(field)))
        if raw is None:
            result[field] = "missing"
            continue
        if not isinstance(raw, str):
            raise ValueError(f"{field}: expected a rating string, received {raw!r}")
        value = raw.strip().lower()
        if value in ("u", "unclear"):
            value = "unresolved"
        value = VALUE_ALIASES[field].get(value, value)
        if value not in (*definite, *EXTRA.get(field, ()), "unresolved"):
            raise ValueError(f"{field}: unrecognized rating {raw!r}")
        result[field] = value
    return result


def ratio(num, den):
    return num / den if den else None


def agreement(series, fields):
    """Exact agreement over all cards and among jointly definite ratings."""
    complete = agreeing = definite = agreeing_definite = 0
    table = defaultdict(Counter)
    for left, right in series:
        a = tuple(left[f] for f in fields)
        b = tuple(right[f] for f in fields)
        if len(fields) == 1:
            table[a[0]][b[0]] += 1
        rated = "missing" not in a and "missing" not in b
        jointly_definite = all(left[f] in DEFINITE[f] and right[f] in DEFINITE[f] for f in fields)
        complete += rated
        agreeing += rated and a == b
        definite += jointly_definite
        agreeing_definite += jointly_definite and a == b
    result = {
        "n_cards": len(series), "n_jointly_rated": complete, "exact_agreements": agreeing,
        "agreement_all_cards": ratio(agreeing, len(series)),
        "agreement_jointly_rated": ratio(agreeing, complete),
        "n_jointly_definite": definite, "definite_exact_agreements": agreeing_definite,
        "agreement_jointly_definite": ratio(agreeing_definite, definite),
    }
    if len(fields) == 1:
        result["confusion_reader1_to_reader2"] = dict(table)
    return result


def decision(row, field):
    """Return a shared definite class, or the reason for withholding it."""
    left, right = (reader[field] for reader in row["ratings"])
    if "missing" in (left, right):
        return "missing"
    if left != right:
        return "disagreement"
    return left


def class_rates(rows, field, mapping):
    """Evaluate each reader and definite consensus against the v101 chart."""
    decisions = {
        "reader1": lambda row: row["ratings"][0][field],
        "reader2": lambda row: row["ratings"][1][field],
        "consensus": lambda row: decision(row, field),
    }
    report = {}
    for observer, classify in decisions.items():
        by_symbol = {}
        for symbol, expected in V101_REFERENCE.items():
            observed = Counter(classify(row) for row in rows if row["symbol"] == symbol)
            n = observed.total()
            definite = sum(observed[result] for result in mapping)
            correct = sum(observed[result] for result, label in mapping.items() if label == expected)
            by_symbol[symbol] = {
                "n_cards": n, "decisions": dict(observed), "n_definite": definite,
                "n_chart_agreement": correct, "coverage": ratio(definite, n),
                "chart_agreement_all_cards": ratio(correct, n),
                "chart_agreement_definite": ratio(correct, definite),
            }
        total = sum(v["n_cards"] for v in by_symbol.values())
        definite = sum(v["n_definite"] for v in by_symbol.values())
        correct = sum(v["n_chart_agreement"] for v in by_symbol.values())
        report[observer] = {"by_symbol": by_symbol, "n_cards": total, "n_definite": definite,
                            "n_chart_agreement": correct, "coverage": ratio(definite, total),
                            "chart_agreement_all_cards": ratio(correct, total),
                            "chart_agreement_definite": ratio(correct, definite)}
    return report


def crop_summary(rows):
    series = [row["ratings"] for row in rows]
    return {
        "agreement": {field: agreement(series, (field,)) for field in DEFINITE},
        "all_variant_features_together": agreement(series, ("closure", "aperture", "projection", "reference")),
        "chart_reference": class_rates(rows, "reference", {"R1": "R1", "R2": "R2"}),
        "chart_projection_sensitivity": class_rates(rows, "projection", PROJECTION_REFERENCE),
    }


def pair_result(members, field, mapping):
    shared = {symbol: decision(row, field) for symbol, row in members.items()}
    mapped = tuple(mapping.get(shared[symbol]) for symbol in ("o", "A"))
    orientation = {
        ("R1", "R2"): "expected", ("R2", "R1"): "reverse",
        ("R1", "R1"): "both_R1", ("R2", "R2"): "both_R2",
    }.get(mapped, "no_consensus")
    return {"decisions": shared, "orientation": orientation}


def orientation_counts(rows, field):
    counts = dict.fromkeys(ORIENTATIONS, 0)
    for row in rows:
        counts[row[field]["orientation"]] += 1
    eligible = len(rows) - counts["no_consensus"]
    complementary = counts["expected"] + counts["reverse"]
    return {
        "n_complete_located_pairs": len(rows), "n_jointly_definite_agreed_pairs": eligible,
        "n_complementary": complementary, "counts": counts,
        "complementary_among_definite": ratio(complementary, eligible),
        "expected_among_definite": ratio(counts["expected"], eligible),
        "expected_among_complementary": ratio(counts["expected"], complementary),
    }


def grouped_pairs(rows, field):
    result = {"all": orientation_counts(rows, field)}
    for dimension in ("hand", "panel", "canvas"):
        groups = defaultdict(list)
        for row in rows:
            groups[row[dimension]].append(row)
        result[f"by_{dimension}"] = {name: orientation_counts(group, field)
                                     for name, group in groups.items()}
    return result


def panel_and_canvas(row):
    geometry = row.get("geometry") or {}
    panel = row.get("page") or row.get("panel") or geometry.get("page")
    canvas = row.get("iiif_canvas") or geometry.get("iiif_canvas")
    return panel or "unknown", canvas or "unknown"


def _pairs(key, positions):
    def pair_index(rows):
        indexed = defaultdict(dict)
        for row in rows:
            pair, symbol = str(row["pair_id"]), row["symbol"]
            if symbol not in V101_REFERENCE or symbol in indexed[pair]:
                raise ValueError(f"Unexpected or duplicate pair member: {pair}, {symbol!r}")
            indexed[pair][symbol] = row
        return indexed

    located = pair_index(key)
    assessed = pair_index(positions or [])
    complete = []
    incomplete = []
    for pair in sorted(set(located) | set(assessed)):
        members = located[pair]
        if members.keys() != V101_REFERENCE.keys():
            missing = {}
            for symbol in V101_REFERENCE.keys() - members.keys():
                prior = assessed.get(pair, {}).get(symbol, {})
                missing[symbol] = (prior.get("join", {}).get("reason") or
                                   ("not in the blind deck" if prior.get("available") else "no located crop"))
            incomplete.append({"pair_id": pair, "located": list(members), "missing": missing})
            continue
        paired = list(members.values())
        hands = {str(row["hand"]) for row in paired}
        panels = {panel_and_canvas(row)[0] for row in paired}
        canvases = sorted({panel_and_canvas(row)[1] for row in paired})
        if len(hands) != 1 or len(panels) != 1:
            raise ValueError(f"Matched pair {pair} spans conflicting hands or panels")
        complete.append({
            "pair_id": pair, "hand": hands.pop(), "panel": panels.pop(),
            "canvas": " + ".join(canvases),
            "blind_codes": {symbol: row["blind_code"] for symbol, row in members.items()},
            "geometry_sensitivity": {symbol: row["geometry_sensitivity"] for symbol, row in members.items()
                                     if row.get("geometry_sensitivity")},
            "reference": pair_result(members, "reference", {"R1": "R1", "R2": "R2"}),
            "projection": pair_result(members, "projection", PROJECTION_REFERENCE),
        })
    return complete, incomplete


def score(key, reader1, reader2, positions=None):
    codes = [row["blind_code"] for row in key]
    known = set(codes)
    if len(codes) != len(known):
        raise ValueError("Duplicate blind crop code")
    for n, reader in enumerate((reader1, reader2), 1):
        extra = sorted(set(reader) - known)
        if extra:
            raise ValueError(f"Reader {n} returned unknown crop codes: {', '.join(extra)}")
    crops = [
        {**row, "ratings": [normalized_rating(reader.get(row["blind_code"], {}))
                             for reader in (reader1, reader2)]}
        for row in key
    ]
    complete, incomplete = _pairs(crops, positions)
    strict = [row for row in complete if not row["geometry_sensitivity"]]
    populations = {}
    for name, pairs in (("strict_complete_pairs", strict),
                        ("all_complete_pairs_with_geometry_sensitivity", complete)):
        included = {pair["pair_id"] for pair in pairs}
        rows = [crop for crop in crops if str(crop["pair_id"]) in included]
        populations[name] = {
            "n_hands": len({pair["hand"] for pair in pairs}),
            "n_panels": len({pair["panel"] for pair in pairs}),
            "n_canvases": len({panel_and_canvas(crop)[1] for crop in rows} - {"unknown"}),
            "crop_summary": crop_summary(rows),
            "reference_orientations": grouped_pairs(pairs, "reference"),
            "projection_orientations": grouped_pairs(pairs, "projection"),
        }
    return {
        "v101_chart_reference": V101_REFERENCE,
        "projection_sensitivity_reference": PROJECTION_REFERENCE,
        "denominators": {
            "agreement": "All cards includes missing cards. Exact agreements require a rating from both readers.",
            "reference_class": "Only R1 and R2 are definite. Neither, unresolved, disagreement and missing remain visible.",
            "projection_class": "Only a shared present or absent call gives a consensus projection decision.",
            "pair_orientation": "Each member must independently receive the same definite class from both readers.",
            "geometry": "Strict pairs exclude the entire pair if either crop has a geometry_sensitivity flag.",
        },
        "all_deck_crops": crop_summary(crops),
        "pair_populations": populations,
        "complete_pairs": complete,
        "incomplete_pairs": incomplete,
        "input_position_roster_included": positions is not None,
        "ratings": [{"blind_code": row["blind_code"], "reader1": reader1.get(row["blind_code"]),
                     "reader2": reader2.get(row["blind_code"])} for row in key],
    }


def plot_projection(report, path):
    """Plot counts by v101 symbol, retaining unresolved and conflicting ratings."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.ticker import MaxNLocator

    layout = (
        ("present", "Yes", "#216a8b"),
        ("absent", "No", "#c89552"),
        ("unresolved", "Unresolved", "#8d737e"),
        ("disagreement", "Disagreement", "#6f7c55"),
        ("missing", "Missing rating", "#a6abae"),
    )
    populations = report["pair_populations"]
    chart_titles = {
        "strict_complete_pairs": "Strict complete pairs",
        "all_complete_pairs_with_geometry_sensitivity": "With secondary geometry",
    }
    symbols = tuple(V101_REFERENCE)
    fig, axes = plt.subplots(1, len(chart_titles), figsize=(8.5, 4), sharey=True)
    for ax, (name, title) in zip(axes, chart_titles.items(), strict=True):
        by_symbol = populations[name]["crop_summary"]["chart_projection_sensitivity"]["consensus"]["by_symbol"]
        base = [0] * len(symbols)
        for result, label, color in layout:
            heights = [by_symbol[symbol]["decisions"].get(result, 0) for symbol in symbols]
            ax.bar(symbols, heights, bottom=base, label=label, color=color)
            base = [prior + added for prior, added in zip(base, heights, strict=True)]
        ax.set_title(title)
        ax.set_xlabel("v101 symbol")
        ax.yaxis.set_major_locator(MaxNLocator(integer=True))
    axes[0].set_ylabel("Located glyphs")
    fig.suptitle("Lower-right projection calls by two blind readers")
    handles, labels = axes[0].get_legend_handles_labels()
    fig.legend(handles, labels, loc="lower center", ncol=len(layout), frameon=False)
    fig.tight_layout(rect=(0, 0.1, 1, 0.95))
    fig.savefig(path, dpi=160)
    plt.close(fig)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("reader1", type=Path)
    parser.add_argument("reader2", type=Path)
    parser.add_argument("--key", type=Path, default=Path(__file__).with_name("private-crop-key.json"))
    parser.add_argument("--positions", type=Path, help="Full geometry roster, including unresolved crops.")
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--projection-plot", type=Path, help="Optional image of consensus projection counts.")
    args = parser.parse_args()
    paths = {"key": args.key, "reader1": args.reader1, "reader2": args.reader2}
    if args.positions:
        paths["positions"] = args.positions
    outputs = [path.resolve() for path in (args.out, args.projection_plot) if path]
    if len(set(outputs)) != len(outputs) or set(outputs) & {path.resolve() for path in paths.values()}:
        parser.error("Output paths must be distinct from one another and from inputs")
    raw = {name: path.read_bytes() for name, path in paths.items()}
    report = score(**{name: json.loads(data) for name, data in raw.items()})
    report["input_sha256"] = {name: sha256(data).hexdigest() for name, data in raw.items()}
    args.out.write_text(json.dumps(report, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8")
    if args.projection_plot:
        plot_projection(report, args.projection_plot)


if __name__ == "__main__":
    main()

