"""Measure a simple lower-right ink extent proxy, separate from visual ratings."""
import hashlib
import json
from pathlib import Path
import re
from statistics import median

import numpy as np
from PIL import Image

ROOT = Path(__file__).resolve().parent
LEVELS = (0.45, 0.55, 0.65)
REGION = re.compile(r"/(\d+),(\d+),\d+,\d+/full/0/default\.jpg$")


def height_proxy(record, gray_fraction, margin=0, reference_band="center"):
    url = record["native_crop_url"]
    origin_x, origin_y = map(int, REGION.search(url).groups())
    path = ROOT / "native-cache" / (hashlib.sha256(url.encode()).hexdigest() + ".jpg")
    native_xyxy = record["glyph_rect"]
    xyxy = [value - origin for value, origin in zip(native_xyxy, (origin_x, origin_y) * 2, strict=True)]
    image = Image.open(path).convert("L")
    expanded = (
        max(0, xyxy[0] - margin), max(0, xyxy[1] - margin),
        min(image.width, xyxy[2] + margin), min(image.height, xyxy[3] + margin),
    )
    assert expanded[0] < expanded[2] and expanded[1] < expanded[3]
    part = image.crop(expanded)
    gray = np.array(part, dtype=float)
    low, upper = np.quantile(gray, (0.12, 0.85))
    if upper - low < 18:
        return None
    foreground = gray <= upper - gray_fraction * (upper - low)
    height, width = gray.shape
    low, high = (0.35, 0.62) if reference_band == "center" else (0.08, 0.36)
    mid = foreground[:, int(low * width):int(high * width)]
    right = foreground[:, int(0.64 * width):int(0.94 * width)]
    positions = [np.nonzero(np.count_nonzero(block, axis=1) >= 2)[0] for block in (mid, right)]
    if any(len(rows) < 3 for rows in positions):
        return None
    # Quantile rather than final pixel protects against a single isolated dark pixel row.
    quantiles = [np.quantile(rows, 0.93) for rows in positions]
    return float((quantiles[1] - quantiles[0]) / height)


def main():
    key = json.loads((ROOT / "private-crop-key.json").read_text())
    secondary = {row["pair_id"] for row in key if "geometry_sensitivity" in row}

    def record_level(level, margin, reference_band):
        by_pair = {}
        for record in key:
            pair = by_pair.setdefault(record["pair_id"], {})
            pair[record["symbol"]] = height_proxy(record, level, margin, reference_band)
        contrasts = {
            pair: result["A"] - result["o"] for pair, result in sorted(by_pair.items())
            if all(result.get(symbol) is not None for symbol in ("o", "A"))
        }
        return {
            "available_pairs": len(contrasts),
            "A_has_larger_proxy": sum(delta > 1e-10 for delta in contrasts.values()),
            "o_has_larger_proxy": sum(delta < -1e-10 for delta in contrasts.values()),
            "ties": sum(abs(delta) <= 1e-10 for delta in contrasts.values()),
            "median_A_minus_o": median(contrasts.values()) if contrasts else None,
            "strict_pairs": sum(pair not in secondary for pair in contrasts),
            "strict_A_has_larger_proxy": sum(delta > 1e-10 for pair, delta in contrasts.items() if pair not in secondary),
            "per_pair_contrast": contrasts,
        }

    per_level = {str(level): record_level(level, 0, "center") for level in LEVELS}
    stress_results = {
        f"band={band},padding={margin},contrast={level}": record_level(level, margin, band)
        for band in ("left", "center")
        for margin in (-2, 0, 2)
        for level in LEVELS
    }
    result = {
        "method": (
            "Measure position of low rows with ink in the central and right bands of each "
            "located glyph's native bounding rectangle. The 93rd percentile of accepted "
            "rows on the right minus the corresponding central percentile, divided by "
            "glyph height, is an exploratory projection proxy. Three contrast fractions "
            "and every available comparison are shown. This proxy depends on the "
            "letter-coordinate crop and cannot determine pen continuity or the class."
        ),
        "results": per_level,
        "supplementary_crop_and_reference_band_sensitivity": stress_results,
    }
    (ROOT / "outline-proxy.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps({key: {k: v for k, v in row.items() if k != "per_pair_contrast"}
                      for key, row in per_level.items()}, indent=2))


if __name__ == "__main__":
    main()

