"""Stress-test the geometric proxy against independent row-slope estimates."""
from collections import defaultdict
import csv
from itertools import combinations
import json
from pathlib import Path
from statistics import median

from measure_outline_proxy import height_proxy, LEVELS


ROOT = Path(__file__).resolve().parent


def line_slope(words, ordinate):
    anchors = []
    for r in words:
        try:
            x0, y0, x1, y1 = (int(r[f"box_{key}"]) for key in ("x0", "y0", "x1", "y1"))
        except ValueError:
            continue
        y = y1 if ordinate == "bottom_envelope" else (y0 + y1) / 2
        anchors.append(((x0 + x1) / 2, y))
    if len(anchors) < 4:
        return None
    ratios = [(yb - ya) / (xb - xa) for (xa, ya), (xb, yb) in combinations(anchors, 2)
              if abs(xb - xa) >= 100]
    return median(ratios) if len(ratios) >= 4 else None


def corrected_proxy(row, words, threshold, ordinate):
    line = [w for w in words[row["locus"]] if w["image"] == row["image"]]
    slope = line_slope(line, ordinate)
    estimate = height_proxy(row, threshold)
    if slope is None or estimate is None:
        return None
    x0, y0, x1, y1 = row["glyph_rect"]
    # Difference in nominal horizontal midpoints of the center and right bands.
    x_displacement = (0.79 - 0.485) * (x1 - x0)
    correction = slope * x_displacement / (y1 - y0)
    return {"native_dx_between_bands": x_displacement, "relative_correction": correction,
            "raw_proxy": estimate, "corrected_proxy": estimate - correction,
            "slope_px_y_per_px_x": slope}


def main():
    key = json.loads((ROOT / "private-crop-key.json").read_text())
    required = {r["locus"] for r in key}
    words = defaultdict(list)
    with (ROOT / "words.tsv").open(newline="") as src:
        for row in csv.DictReader(src, delimiter="\t"):
            if row["locus"] in required:
                words[row["locus"]].append(row)
    estimates = {}
    for ordinate in ("bottom_envelope", "center"):
        for threshold in LEVELS:
            members = defaultdict(dict)
            for row in key:
                e = corrected_proxy(row, words, threshold, ordinate)
                if e is not None:
                    members[row["pair_id"]][row["symbol"]] = e
            pairs = {}
            by_hand = defaultdict(list)
            hands = {row["pair_id"]: row["hand"] for row in key}
            for pair, results in members.items():
                if results.keys() == {"A", "o"}:
                    delta = results["A"]["corrected_proxy"] - results["o"]["corrected_proxy"]
                    by_hand[hands[pair]].append(delta)
                    pairs[pair] = {**results, "difference_A_minus_o": delta}
            estimates[f"{ordinate}-{threshold}"] = {
                "available_pairs": len(pairs),
                "A_larger": sum(row["difference_A_minus_o"] > 1e-10 for row in pairs.values()),
                "by_hand": {
                    hand: {"pairs": len(values), "A_larger": sum(v > 1e-10 for v in values)}
                    for hand, values in sorted(by_hand.items())
                },
                "matched_pairs": pairs,
            }
    result = {
        "method": (
            "Estimate local line slope from the median of all same-image word box slopes "
            "with horizontal separation at least 100 pixels. Require at least four boxes "
            "and four qualifying slopes. Subtract the estimated y change between the "
            "nominal center of the two glyph bands. Consider word-box center and bottom "
            "as two imperfect measures of row position. This is an exploratory sensitivity "
            "to writing inclination on the originally frozen deck."
        ),
        "results": estimates,
    }
    (ROOT / "outline-slope-sensitivity.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps({k: {field: value for field, value in row.items() if field != "matched_pairs"}
                      for k, row in estimates.items()}, indent=2))


if __name__ == "__main__":
    main()
